ALTER TABLE public.orders ADD COLUMN order_number text UNIQUE, ADD COLUMN received_at timestamptz, ADD COLUMN shipped_at timestamptz, ADD COLUMN out_for_delivery_at timestamptz, ADD COLUMN delivered_at timestamptz, ADD COLUMN cancelled_at timestamptz;
CREATE SEQUENCE public.order_number_seq;
CREATE OR REPLACE FUNCTION public.assign_order_number() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.order_number IS NULL THEN NEW.order_number := 'T8-' || to_char(now(), 'YYMMDD') || '-' || lpad(nextval('public.order_number_seq')::text, 5, '0'); END IF; RETURN NEW; END; $$;
CREATE TRIGGER assign_order_number BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.assign_order_number();
CREATE OR REPLACE FUNCTION public.stamp_order_status() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN CASE NEW.status WHEN 'received' THEN NEW.received_at := coalesce(NEW.received_at, now()); WHEN 'shipped' THEN NEW.shipped_at := coalesce(NEW.shipped_at, now()); WHEN 'out_for_delivery' THEN NEW.out_for_delivery_at := coalesce(NEW.out_for_delivery_at, now()); WHEN 'delivered' THEN NEW.delivered_at := coalesce(NEW.delivered_at, now()); WHEN 'cancelled' THEN NEW.cancelled_at := coalesce(NEW.cancelled_at, now()); END CASE; END IF; RETURN NEW; END; $$;
CREATE TRIGGER stamp_order_status BEFORE UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.stamp_order_status();
ALTER TABLE public.orders ADD CONSTRAINT orders_status_valid CHECK (status IN ('pending','paid','received','shipped','out_for_delivery','delivered','cancelled'));
CREATE OR REPLACE FUNCTION public.track_order(p_order_number text, p_phone text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE result jsonb; BEGIN IF length(trim(coalesce(p_phone,''))) < 6 OR length(coalesce(p_order_number,'')) > 40 THEN RETURN NULL; END IF; SELECT jsonb_build_object('orderNumber', o.order_number, 'status', o.status, 'createdAt', o.created_at, 'updatedAt', o.updated_at, 'receivedAt', o.received_at, 'shippedAt', o.shipped_at, 'outForDeliveryAt', o.out_for_delivery_at, 'deliveredAt', o.delivered_at, 'cancelledAt', o.cancelled_at, 'town', o.town, 'items', (SELECT coalesce(jsonb_agg(jsonb_build_object('name',i.name,'quantity',i.quantity)), '[]'::jsonb) FROM public.order_items i WHERE i.order_id = o.id)) INTO result FROM public.orders o WHERE o.order_number = upper(trim(p_order_number)) AND regexp_replace(o.phone, '[^0-9]', '', 'g') = regexp_replace(p_phone, '[^0-9]', '', 'g') LIMIT 1; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.track_order(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.track_order(text,text) TO anon, authenticated;